arguments.command:
cd /workspace/submission && rm -rf __pycache__ && python3 - <<'EOF'
import os,stat
entries=0;total=0;bad=[];files=[]
for root,ds,fs in os.walk('.'):
    entries+=len(ds)+len(fs)
    for name in ds:
        p=os.path.join(root,name);st=os.lstat(p)
        if stat.S_ISLNK(st.st_mode) or not stat.S_ISDIR(st.st_mode):bad.append(p)
    for name in fs:
        p=os.path.join(root,name);st=os.lstat(p);total+=st.st_size;files.append(p)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:bad.append(p)
print({'entries':entries,'file_bytes':total,'bad':bad,'files':sorted(files)})
EOF
cd /workspace && python3 -I -B submission/campaign.py <<'EOF'
